 export const pageReady = true;
+
+export function setMenuOpen(button, menu, open) {
+  menu.hidden = !open;
+  button.setAttribute("aria-expanded", String(open));
+}
+
+if (typeof document !== "undefined") {
+  const menuButton = document.querySelector(".menu-button");
+  const menu = document.querySelector("#site-menu");
+  const search = document.querySelector("#project-search");
+  const filters = [...document.querySelectorAll(".filter")];
+  const cards = [...document.querySelectorAll(".project-card")];
+  const emptyState = document.querySelector(".empty-state");
+  let activeFilter = "all";
+
+  const mobile = () => window.matchMedia("(max-width: 720px)").matches;
+  setMenuOpen(menuButton, menu, !mobile());
+
+  menuButton.addEventListener("click", () => {
+    setMenuOpen(menuButton, menu, menuButton.getAttribute("aria-expanded") !== "true");
+  });
+
+  menu.addEventListener("click", (event) => {
+    if (mobile() && event.target.closest("a")) setMenuOpen(menuButton, menu, false);
+  });
+
+  document.addEventListener("keydown", (event) => {
+    if (event.key === "Escape" && mobile() && !menu.hidden) {
+      setMenuOpen(menuButton, menu, false);
+      menuButton.focus();
+    }
+  });
+
+  window.addEventListener("resize", () => setMenuOpen(menuButton, menu, !mobile()));
+
+  function updateProjects() {
+    const query = search.value.trim().toLocaleLowerCase();
+    let visible = 0;
+    cards.forEach((card) => {
+      const matchesFilter = activeFilter === "all" || card.dataset.status === activeFilter;
+      const matchesSearch = card.dataset.search.includes(query);
+      card.hidden = !(matchesFilter && matchesSearch);
+      if (!card.hidden) visible += 1;
+    });
+    emptyState.hidden = visible !== 0;
+  }
+
+  search.addEventListener("input", updateProjects);
+  filters.forEach((filter) => filter.addEventListener("click", () => {
+    activeFilter = filter.dataset.filter;
+    filters.forEach((item) => {
+      const selected = item === filter;
+      item.classList.toggle("active", selected);
+      item.setAttribute("aria-pressed", String(selected));
+    });
+    updateProjects();
+  }));
+}
