@@ -1,3 +1,104 @@
-body { margin: 0; font-family: system-ui, sans-serif; }
-main, header { padding: 1rem; }
-.projects { display: block; }
+:root {
+  --ink: #17211b;
+  --muted: #68736c;
+  --line: #dfe5e0;
+  --paper: #f7f8f5;
+  --surface: #ffffff;
+  --green: #256a4a;
+  --green-dark: #174d35;
+  --green-soft: #e6f2ea;
+  --focus: #ef9f3b;
+}
+
+* { box-sizing: border-box; }
+html { color-scheme: light; scroll-behavior: smooth; }
+body { margin: 0; min-width: 320px; background: var(--paper); color: var(--ink); font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
+button, input { font: inherit; }
+button, a { -webkit-tap-highlight-color: transparent; }
+button { color: inherit; }
+
+.skip-link { position: fixed; z-index: 20; top: .5rem; left: .5rem; padding: .7rem 1rem; background: var(--ink); color: white; border-radius: .5rem; transform: translateY(-150%); }
+.skip-link:focus { transform: translateY(0); }
+.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
+
+.site-header { height: 72px; display: flex; align-items: center; gap: 2rem; padding: 0 clamp(1rem, 4vw, 4rem); border-bottom: 1px solid var(--line); background: rgba(255,255,255,.9); backdrop-filter: blur(12px); }
+.brand { display: flex; align-items: center; gap: .7rem; color: var(--ink); text-decoration: none; font-weight: 750; letter-spacing: -.02em; }
+.brand-mark { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; color: #fff; background: var(--green); font-size: .7rem; letter-spacing: .02em; }
+.site-menu { display: flex; align-self: stretch; gap: 1.75rem; }
+.site-menu a { position: relative; display: flex; align-items: center; color: var(--muted); text-decoration: none; font-size: .9rem; font-weight: 600; }
+.site-menu a:hover, .site-menu a.active { color: var(--ink); }
+.site-menu a.active::after { content: ""; position: absolute; inset: auto 0 -1px; height: 2px; background: var(--green); }
+.avatar { margin-left: auto; width: 36px; height: 36px; border: 0; border-radius: 50%; background: #e1e8e2; font-weight: 700; font-size: .75rem; cursor: pointer; }
+.menu-button { display: none; }
+
+main { width: min(1180px, calc(100% - 2rem)); margin: 0 auto; padding: clamp(2.5rem, 7vw, 5rem) 0 5rem; }
+.hero { display: flex; align-items: end; justify-content: space-between; gap: 2rem; margin-bottom: 2.25rem; }
+.eyebrow { margin: 0 0 .7rem; color: var(--green); text-transform: uppercase; letter-spacing: .13em; font-size: .72rem; font-weight: 800; }
+h1 { margin: 0; font-family: Georgia, "Times New Roman", serif; font-size: clamp(2.7rem, 6vw, 4.5rem); font-weight: 500; line-height: .96; letter-spacing: -.045em; }
+.intro { max-width: 40rem; margin: 1rem 0 0; color: var(--muted); font-size: clamp(.95rem, 2vw, 1.08rem); }
+.primary-button { min-height: 44px; flex: none; display: inline-flex; align-items: center; gap: .4rem; padding: .75rem 1.1rem; border: 1px solid var(--green-dark); border-radius: .65rem; background: var(--green); color: white; font-weight: 700; cursor: pointer; box-shadow: 0 5px 15px rgba(37,106,74,.16); }
+.primary-button:hover { background: var(--green-dark); transform: translateY(-1px); }
+
+.browser { overflow: hidden; border: 1px solid var(--line); border-radius: 16px; background: var(--surface); box-shadow: 0 18px 50px rgba(25,46,34,.06); }
+.toolbar { min-height: 74px; display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: .85rem 1rem; border-bottom: 1px solid var(--line); }
+.search { width: min(320px, 100%); position: relative; display: flex; align-items: center; }
+.search svg { position: absolute; left: .8rem; width: 18px; fill: none; stroke: var(--muted); stroke-width: 2; stroke-linecap: round; }
+.search input { width: 100%; height: 42px; padding: 0 .8rem 0 2.45rem; border: 1px solid var(--line); border-radius: .6rem; outline: none; background: #fbfcfa; color: var(--ink); }
+.search input:focus { border-color: var(--green); box-shadow: 0 0 0 3px rgba(37,106,74,.12); }
+.filter-group { display: flex; gap: .25rem; padding: .2rem; border-radius: .65rem; background: var(--paper); }
+.filter { min-height: 36px; padding: .35rem .7rem; border: 0; border-radius: .5rem; background: transparent; color: var(--muted); font-size: .82rem; font-weight: 650; cursor: pointer; }
+.filter span { margin-left: .25rem; opacity: .65; }
+.filter:hover { color: var(--ink); }
+.filter.active { color: var(--ink); background: white; box-shadow: 0 1px 4px rgba(22,34,27,.1); }
+
+.list-header, .project-card { display: grid; grid-template-columns: minmax(280px, 1fr) 110px 120px 44px; align-items: center; gap: 1rem; }
+.list-header { padding: .7rem 1.25rem; border-bottom: 1px solid var(--line); background: #fbfcfa; color: #7b857e; text-transform: uppercase; letter-spacing: .09em; font-size: .66rem; font-weight: 800; }
+.project-card { min-height: 96px; padding: 1rem 1.25rem; border-bottom: 1px solid var(--line); transition: background .2s ease; }
+.project-card:last-child { border-bottom: 0; }
+.project-card:hover { background: #fafbf9; }
+.project-card[hidden] { display: none; }
+.project-identity { min-width: 0; display: flex; align-items: center; gap: .95rem; }
+.project-icon { flex: none; display: grid; place-items: center; width: 48px; height: 48px; border-radius: 13px; font-family: Georgia, serif; font-size: 1.25rem; font-weight: 700; }
+.atlas { color: #315d4b; background: #dcebe2; }.beacon { color: #765829; background: #f3e7c9; }.canopy { color: #42647d; background: #dce9f0; }.drift { color: #684e78; background: #e9e0ef; }.ember { color: #875246; background: #f0dfda; }.fjord { color: #506574; background: #dfe7eb; }
+.project-card h2 { margin: 0 0 .28rem; font-family: Georgia, serif; font-size: 1.18rem; line-height: 1.1; }
+.project-card p { overflow: hidden; margin: 0; color: var(--muted); font-size: .83rem; text-overflow: ellipsis; white-space: nowrap; }
+.status { width: fit-content; display: inline-flex; align-items: center; gap: .4rem; padding: .3rem .55rem; border-radius: 999px; font-size: .72rem; font-weight: 700; }
+.status::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
+.active-status { color: #246b49; background: var(--green-soft); }
+.archived-status { color: #6f7771; background: #edf0ed; }
+time { color: var(--muted); font-size: .8rem; }
+.more-button { width: 40px; height: 40px; border: 0; border-radius: .5rem; background: transparent; color: var(--muted); cursor: pointer; letter-spacing: .08em; }
+.more-button:hover { background: #edf1ed; color: var(--ink); }
+.empty-state { padding: 4rem 1rem; text-align: center; }
+.empty-state span { font-size: 2rem; color: var(--muted); }.empty-state h2 { margin: .7rem 0 .3rem; font-family: Georgia, serif; }.empty-state p { margin: 0; color: var(--muted); }
+
+:focus-visible { outline: 3px solid var(--focus); outline-offset: 3px; }
+@media (prefers-reduced-motion: no-preference) { button, a, .site-menu { transition: color .18s ease, background .18s ease, transform .18s ease, opacity .18s ease; } }
+
+@media (max-width: 720px) {
+  .site-header { position: relative; height: 64px; padding: 0 1rem; gap: .65rem; }
+  .brand { font-size: .95rem; }
+  .brand-mark { width: 32px; height: 32px; }
+  .avatar { display: none; }
+  .menu-button { margin-left: auto; min-height: 42px; display: inline-flex; align-items: center; gap: .5rem; padding: .5rem .65rem; border: 1px solid var(--line); border-radius: .6rem; background: white; font-size: .82rem; font-weight: 700; }
+  .menu-icon, .menu-icon::before, .menu-icon::after { display: block; width: 16px; height: 2px; border-radius: 1px; background: currentColor; }
+  .menu-icon { position: relative; }.menu-icon::before, .menu-icon::after { content: ""; position: absolute; left: 0; }.menu-icon::before { top: -5px; }.menu-icon::after { top: 5px; }
+  .site-menu { position: absolute; z-index: 10; inset: calc(100% + 8px) 1rem auto; display: grid; gap: .25rem; padding: .5rem; border: 1px solid var(--line); border-radius: .75rem; background: white; box-shadow: 0 18px 45px rgba(22,34,27,.15); }
+  .site-menu[hidden] { display: none; }
+  .site-menu a { min-height: 44px; padding: .65rem .8rem; border-radius: .45rem; }
+  .site-menu a.active { background: var(--green-soft); }.site-menu a.active::after { display: none; }
